# Given 2 sequences, A : B, provide the Hamming Distance,
#Ie: if A = CATA, B = CATT,
# Hamming distance = 1. As 
# A != T.

#Supplied sequences
sequence1 = ""
sequence2 = ""

similar = 0
different = 0

# loop for total amount in seq
# this accounts for the SHORTEST sequence, it is insufficient for mismatched n sequences.

for char1, char2 in zip(sequence1,sequence2):
        if char1 == char2:
            similar += 1
        else:
            different += 1
print(different)
# different denotes the hamming distance. 

